  let m = v.match(/\/folders\/([A-Za-z0-9_-]{10,})/);
  if (m) return { type: 'folder', id: m[1] };
  m = v.match(/\/file\/d\/([A-Za-z0-9_-]{10,})/) || v.match(/[?&]id=([A-Za-z0-9_-]{10,})/);
  if (m) return { type: 'file', id: m[1] };
